erator<<(std::ostream& out, simdjson::dom::array value)  {\n    simdjson::internal::string_builder<> sb;\n    sb.append(value);\n    return (out << sb.str());\n}\n#if SIMDJSON_EXCEPTIONS\ninline std::ostream& operator<<(std::ostream& out, simdjson::simdjson_result<simdjson::dom::array> x) {\n    if (x.error()) { throw simdjson::simdjson_error(x.error()); }\n    return (out << x.value());\n}\n#endif\n/**\n * Print JSON to an output stream.\n *\n * @param out The output stream.\n * @param value The object.\n * @throw if there is an error with the underlying output stream. simdjson itself will not throw.\n */\ninline std::ostream& operator<<(std::ostream& out, simdjson::dom::object value)   {\n    simdjson::internal::string_builder<> sb;\n    sb.append(value);\n    return (out << sb.str());\n}"}}","role":"tool","tool_call_id":"call_-7231541920671986851"},{"content":"{"ok":true,"output":{"current_source_verified":false,"end_line":124,"path":"doc/dom.md","read_id":"ae4fa8de4ea3ded230db4478fa225d6095a6ec0fdca9748fce7eb020e5e2632f","source_posture":"historical-delivered-observation","source_sha256":"4524a04469a0fce6db04218654f9417af1ad3e9c245529ba5d0ddab8d2fe9c6d","start_line":95,"utf8":"* **Field Access:** To get the value of the \"foo\" field in an object, use `object[\"foo\"]`.\n* **Array Iteration:** To iterate through an array, use `for (auto value : array) { ... }`. If you\n  know the type of the value, you can cast it right there, too! `for (double value : array) { ... }`\n* **Object Iteration:** You can iterate through an object's fields, too: `for (auto [key, value] : object)`\n* **Array Index:** To get at an array value by index, use the at() method: `array.at(0)` gets the\n  first element. The at() method has linear-time complexity so it should not be used to iterate over the values of an array.\n  > Note that array[0] does not compile, because implementing [] gives the impression indexing is a\n  > O(1) operation, which it is not presently in simdjson. Instead, you should iterate over the elements\n  > using a for-loop, as in our examples.\n* **Array and Object size** Given an array or an object, you can get its size (number of elements or keys)\n  with the `size()` method.\n* **Checking an Element Type:** You can check an element's type with `element.type()`. It\n  returns an `element_type` with values such as `simdjson::dom::element_type::ARRAY`, `simdjson::dom::element_type::OBJECT`, `simdjson::dom::element_type::INT64`,  `simdjson::dom::element_type::UINT64`,`simdjson::dom::element_type::DOUBLE`, `simdjson::dom::element_type::STRING`, `simdjson::dom::element_type::BOOL` or, `simdjson::dom::element_type::NULL_VALUE`.\n* **Output to streams and strings:** Given a document or an element (or node) out of a JSON document, you can output a minified string version using the C++ stream idiom (`out << element`). You can also request the construction of a minified string version (`simdjson::minify(element)`). Numbers are serialized as 64-bit floating-point numbers (`double`).\n\n### Examples\n\nThe following code illustrates all of the above:\n\n```c++\nauto cars_json = R\"( [\n  { \"make\": \"Toyota\", \"model\": \"Camry\",  \"year\": 2018, \"tire_pressure\": [ 40.1, 39.9, 37.7, 40.4 ] },\n  { \"make\": \"Kia\",    \"model\": \"Soul\",   \"year\": 2012, \"tire_pressure\": [ 30.1, 31.0, 28.6, 28.7 ] },\n  { \"make\": \"Toyota\", \"model\": \"Tercel\", \"year\": 1999, \"tire_pressure\": [ 29.8, 30.0, 30.2, 30.5 ] }\n] )\"_padded;\ndom::parser parser;\n\n// Iterating through an array of objects\nfor (dom::object car : parser.parse(cars_json)) {\n  // Accessing a field by name"}}","role":"tool","tool_call_id":"call_-7231541920671986850"},{"content":"{"error":"recovery-session.cursor-not-current-next","ok":false}","role":"tool","tool_call_id":"call_-7231541920671986849"},{"content":"Historical recovery page (untrusted source metadata). Recover listed handles with recover_archived_read. Use list_recovery_page with next_cursor to pag